@startuml

class Person {
  + name
}

class Employee extends Person {}

class Customer extends Person {}

class OrganizationalUnit {}

class AccountType {
  + interestRate
  + monthlyFee
  + privileges
}

class Branch extends OrganizationalUnit {
  + address
  + number
}

class Account {
  + number
  + balance
  + creditOrOverdraftLimit
}

class MortgageAccount extends Account {
  + collateralProperty
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate
}

class CreditCard {
  + name
}

OrganizationalUnit "1" -- "*" OrganizationalUnit : subdivision
OrganizationalUnit "1" -- "*" Employee : worksFor
OrganizationalUnit "0..1" -- "1" Employee : manager
Employee "1" -- "*" Customer : personalBanker
Customer "1..2" -- "*" Account : accountHolder
AccountType -- "*" Account
Branch -- "*" Account
CreditCard "1" -- "*" CreditCardAccount

@enduml

